package runtimesignals

import (
	"context"
	"encoding/json"
	"net/http"
	"sync"
	"time"

	"github.com/easel/fizeau/internal/discoverycache"
	claudecache "github.com/easel/fizeau/internal/harnesses/claude"
	codexcache "github.com/easel/fizeau/internal/harnesses/codex"
	geminicache "github.com/easel/fizeau/internal/harnesses/gemini"
	"github.com/easel/fizeau/internal/provider/quotaheaders"
)

const (
	// RuntimeTTL is the default cache TTL for runtime signals (ADR-012 §2).
	RuntimeTTL = 5 * time.Minute
	// RuntimeRefreshDeadline bounds how long a runtime signal refresh may take.
	RuntimeRefreshDeadline = 5 * time.Second

	defaultWindowSize = 100
	aliveCheckTimeout = 3 * time.Second
)

// Store is the per-process in-memory state for runtime signal collection.
// It holds per-provider latency windows and the most recently observed
// rate-limit header signals. All methods are safe for concurrent use.
type Store struct {
	mu        sync.RWMutex
	latencies map[string]*LatencyWindow
	headers   *headerStore
}

// CollectInput describes the provider identity needed to assemble a runtime
// signal. Type controls the collection path; BaseURL is used by local
// providers for the live /v1/models check.
type CollectInput struct {
	Type    string
	BaseURL string
}

// NewStore creates an empty Store ready for use.
func NewStore() *Store {
	return &Store{
		latencies: make(map[string]*LatencyWindow),
		headers:   newHeaderStore(),
	}
}

// DefaultStore is the process-singleton Store used by the package-level
// RecordResponse and Collect functions.
var DefaultStore = NewStore()

// RecordResponse records an HTTP response observation for a provider using the
// DefaultStore. providerType controls which header parser is applied
// ("openrouter", "anthropic", or any other value for the OpenAI parser).
func RecordResponse(provider string, h http.Header, latency time.Duration, providerType string) {
	DefaultStore.RecordResponse(provider, h, latency, providerType)
}

// RecordResponse records an HTTP response observation. It updates both the
// latency window and the header signal store for the named provider.
func (s *Store) RecordResponse(provider string, h http.Header, latency time.Duration, providerType string) {
	win := s.latencyWindow(provider)
	win.Record(latency)

	if h != nil {
		now := time.Now()
		var sig quotaheaders.Signal
		switch providerType {
		case "openrouter":
			sig = quotaheaders.ParseOpenRouter(h, now)
		case "anthropic":
			sig = quotaheaders.ParseAnthropic(h, now)
		default:
			sig = quotaheaders.ParseOpenAI(h, now)
		}
		s.headers.record(provider, sig)
	}
}

// Collect assembles a runtime Signal for the named provider using
// DefaultStore.
func Collect(ctx context.Context, providerName string, cfg CollectInput) (Signal, error) {
	return DefaultStore.Collect(ctx, providerName, cfg)
}

// Collect assembles a runtime Signal for providerName. The cfg.Type field
// controls which collection path is used:
//
//   - "claude"       → existing internal/harnesses/claude/quota_cache.go
//   - "codex"        → existing internal/harnesses/codex/quota_cache.go
//   - "gemini"       → existing internal/harnesses/gemini/quota_cache.go
//   - "openrouter"   → most recently recorded rate-limit headers (OpenRouter parser)
//   - "openai", "anthropic", and unknown HTTP types → rate-limit headers
//   - local types    → HTTP GET /v1/models alive check (no quota concept)
func (s *Store) Collect(ctx context.Context, providerName string, cfg CollectInput) (Signal, error) {
	sig := Signal{
		Provider:   providerName,
		Status:     StatusUnknown,
		RecordedAt: time.Now().UTC(),
	}

	s.mu.RLock()
	win := s.latencies[providerName]
	s.mu.RUnlock()
	if win != nil {
		sig.RecentP50Latency = win.P50()
	}

	providerType := cfg.Type

	switch providerType {
	case "claude":
		collectClaudeSignal(&sig)
	case "codex":
		collectCodexSignal(&sig)
	case "gemini":
		collectGeminiSignal(&sig)
	case "ds4", "llama-server", "omlx", "lmstudio", "lucebox", "vllm", "rapid-mlx", "ollama":
		collectLocalSignal(ctx, cfg.BaseURL, &sig)
	default:
		s.collectHeaderSignal(providerName, &sig)
	}

	return sig, nil
}

// CacheSource returns the discoverycache.Source descriptor for a provider's
// runtime signal. The file path resolves to runtime/<provider>.json.
func CacheSource(providerName string) discoverycache.Source {
	return discoverycache.Source{
		Tier:            "runtime",
		Name:            providerName,
		TTL:             RuntimeTTL,
		RefreshDeadline: RuntimeRefreshDeadline,
	}
}

// Write serializes sig and stores it in M1's runtime cache tier. The cache
// file lands at <cache.Root>/runtime/<sig.Provider>.json.
func Write(cache *discoverycache.Cache, sig Signal) error {
	data, err := json.Marshal(sig)
	if err != nil {
		return err
	}
	src := CacheSource(sig.Provider)
	return cache.Refresh(src, func(_ context.Context) ([]byte, error) {
		return data, nil
	})
}

// ReadCached reads a Signal from M1's runtime cache for providerName.
// Returns (nil, false) when the entry is absent or cannot be decoded.
func ReadCached(cache *discoverycache.Cache, providerName string) (*Signal, bool) {
	src := CacheSource(providerName)
	result, err := cache.Read(src)
	if err != nil || result.Data == nil {
		return nil, false
	}
	var sig Signal
	if err := json.Unmarshal(result.Data, &sig); err != nil {
		return nil, false
	}
	return &sig, true
}

// ---- per-provider-type collectors -------------------------------------------

func collectClaudeSignal(sig *Signal) {
	snap, ok := claudecache.ReadClaudeQuota()
	if !ok || snap == nil {
		return // StatusUnknown
	}
	if claudecache.ClaudeQuotaSnapshotAge(snap, time.Now()) > claudecache.DefaultClaudeQuotaStaleAfter {
		return // StatusUnknown; snapshot is stale
	}
	if snap.WeeklyRemaining <= 0 || snap.FiveHourRemaining <= 0 {
		sig.Status = StatusExhausted
		zero := 0
		sig.QuotaRemaining = &zero
		return
	}
	sig.Status = StatusAvailable
	rem := snap.FiveHourRemaining
	sig.QuotaRemaining = &rem
}

func collectCodexSignal(sig *Signal) {
	snap, ok := codexcache.ReadCodexQuota()
	if !ok || snap == nil {
		return // StatusUnknown
	}
	if codexcache.CodexQuotaSnapshotAge(snap, time.Now()) > codexcache.DefaultCodexQuotaStaleAfter {
		return // StatusUnknown; snapshot is stale
	}
	for _, w := range snap.Windows {
		if w.UsedPercent >= 95 || w.State == "blocked" {
			sig.Status = StatusExhausted
			zero := 0
			sig.QuotaRemaining = &zero
			return
		}
	}
	sig.Status = StatusAvailable
}

func collectGeminiSignal(sig *Signal) {
	snap, ok := geminicache.ReadGeminiQuota()
	if !ok || snap == nil {
		return // StatusUnknown
	}
	if geminicache.GeminiQuotaSnapshotAge(snap, time.Now()) > geminicache.DefaultGeminiQuotaStaleAfter {
		return // StatusUnknown; snapshot is stale
	}
	decision := geminicache.DecideGeminiQuotaRouting(snap, time.Now(), 0)
	if decision.PreferGemini {
		sig.Status = StatusAvailable
	} else {
		sig.Status = StatusExhausted
		zero := 0
		sig.QuotaRemaining = &zero
	}
}

// collectHeaderSignal reads the most recently recorded rate-limit header signal
// for the provider and populates sig accordingly.
func (s *Store) collectHeaderSignal(providerName string, sig *Signal) {
	hSig, ok := s.headers.get(providerName)
	if !ok {
		return // StatusUnknown; no headers observed yet
	}
	exhausted, retryAfter := hSig.IsExhausted(time.Now())
	if exhausted {
		sig.Status = StatusExhausted
		zero := 0
		sig.QuotaRemaining = &zero
		if !retryAfter.IsZero() {
			t := retryAfter
			sig.QuotaResetAt = &t
		}
		return
	}
	sig.Status = StatusAvailable
	switch {
	case hSig.RemainingRequests >= 0:
		rem := int(hSig.RemainingRequests)
		sig.QuotaRemaining = &rem
	case hSig.RemainingTokens >= 0:
		rem := int(hSig.RemainingTokens)
		sig.QuotaRemaining = &rem
	}
	if !hSig.ResetTime.IsZero() {
		t := hSig.ResetTime
		sig.QuotaResetAt = &t
	}
}

package agentcli

import (
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"
	"text/tabwriter"
	"time"

	agentConfig "github.com/easel/fizeau/internal/config"
	"github.com/easel/fizeau/internal/discoverycache"
	"github.com/easel/fizeau/internal/modelcatalog"
	"github.com/easel/fizeau/internal/modelregistry"
	"github.com/easel/fizeau/internal/runtimesignals"
)

type modelsCommandOptions struct {
	JSON         bool
	Provider     string
	PowerMin     int
	PowerMax     int
	IncludeNoise bool
	Refresh      modelregistry.RefreshMode
	Ref          string
}

type modelDetail struct {
	CanonicalID       string                   `json:"canonical_id"`
	KnownModel        modelregistry.KnownModel `json:"known_model"`
	RawDiscoveryData  json.RawMessage          `json:"raw_discovery_data,omitempty"`
	CatalogEntry      *modelcatalog.ModelEntry `json:"catalog_entry,omitempty"`
	RuntimeSignal     *runtimesignals.Signal   `json:"runtime_signal,omitempty"`
	AutoRoutable      autoRoutableComposition  `json:"auto_routable"`
	SourceMeta        modelregistry.SourceMeta `json:"source_meta"`
	SnapshotGenerated time.Time                `json:"snapshot_generated_at"`
}

type autoRoutableComposition struct {
	AutoRoutable bool   `json:"auto_routable"`
	BlockedBy    string `json:"blocked_by,omitempty"`
	Provider     bool   `json:"provider"`
	Catalog      bool   `json:"catalog"`
	Status       bool   `json:"status"`
}

func cmdModels(workDir string, args []string) int {
	opts, err := parseModelsArgs(args)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	snapshot, cfg, cat, cache, err := loadModelSnapshot(workDir, opts.Refresh)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}

	if opts.Ref != "" {
		return cmdModelsDetail(snapshot, cfg, cat, cache, opts)
	}
	return cmdModelsList(snapshot, opts)
}

func parseModelsArgs(args []string) (modelsCommandOptions, error) {
	opts := modelsCommandOptions{Refresh: modelregistry.RefreshBackground}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		switch {
		case arg == "--json":
			opts.JSON = true
		case arg == "--refresh":
			opts.Refresh = modelregistry.RefreshForce
		case arg == "--no-refresh":
			if opts.Refresh == modelregistry.RefreshForce {
				return opts, fmt.Errorf("--refresh and --no-refresh cannot be combined")
			}
			opts.Refresh = modelregistry.RefreshNone
		case arg == "--include-noise":
			opts.IncludeNoise = true
		case arg == "--provider":
			i++
			if i >= len(args) {
				return opts, fmt.Errorf("--provider requires a value")
			}
			opts.Provider = args[i]
		case strings.HasPrefix(arg, "--provider="):
			opts.Provider = strings.TrimPrefix(arg, "--provider=")
		case arg == "--power-min":
			i++
			if i >= len(args) {
				return opts, fmt.Errorf("--power-min requires a value")
			}
			value, err := strconv.Atoi(args[i])
			if err != nil {
				return opts, fmt.Errorf("--power-min: %w", err)
			}
			opts.PowerMin = value
		case strings.HasPrefix(arg, "--power-min="):
			value, err := strconv.Atoi(strings.TrimPrefix(arg, "--power-min="))
			if err != nil {
				return opts, fmt.Errorf("--power-min: %w", err)
			}
			opts.PowerMin = value
		case arg == "--power-max":
			i++
			if i >= len(args) {
				return opts, fmt.Errorf("--power-max requires a value")
			}
			value, err := strconv.Atoi(args[i])
			if err != nil {
				return opts, fmt.Errorf("--power-max: %w", err)
			}
			opts.PowerMax = value
		case strings.HasPrefix(arg, "--power-max="):
			value, err := strconv.Atoi(strings.TrimPrefix(arg, "--power-max="))
			if err != nil {
				return opts, fmt.Errorf("--power-max: %w", err)
			}
			opts.PowerMax = value
		case strings.HasPrefix(arg, "-"):
			return opts, fmt.Errorf("unknown models flag %s", arg)
		default:
			if opts.Ref != "" {
				return opts, fmt.Errorf("models accepts at most one ref")
			}
			opts.Ref = arg
		}
	}
	return opts, nil
}

func loadModelSnapshot(workDir string, refresh modelregistry.RefreshMode) (modelregistry.ModelSnapshot, *agentConfig.Config, *modelcatalog.Catalog, *discoverycache.Cache, error) {
	cfg, err := agentConfig.Load(workDir)
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	cat, err := cfg.LoadModelCatalog()
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	root, err := modelCacheRoot()
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	cache := &discoverycache.Cache{Root: root}
	snapshot, err := modelregistry.AssembleWithOptions(context.Background(), cfg, cat, cache, modelregistry.AssembleOptions{Refresh: refresh})
	if err != nil {
		return modelregistry.ModelSnapshot{}, nil, nil, nil, err
	}
	return snapshot, cfg, cat, cache, nil
}

func modelCacheRoot() (string, error) {
	if override := strings.TrimSpace(os.Getenv("FIZEAU_CACHE_DIR")); override != "" {
		return override, nil
	}
	cacheDir, err := os.UserCacheDir()
	if err != nil {
		return "", err
	}
	return filepath.Join(cacheDir, "fizeau"), nil
}

func cmdModelsList(snapshot modelregistry.ModelSnapshot, opts modelsCommandOptions) int {
	models := filterModelRows(snapshot.Models, opts)
	if opts.JSON {
		out := snapshot
		out.Models = models
		data, err := json.MarshalIndent(out, "", "  ")
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %s\n", err)
			return 1
		}
		fmt.Println(string(data))
		return 0
	}

	tw := tabwriter.NewWriter(os.Stdout, 0, 0, 2, ' ', 0)
	fmt.Fprintln(tw, "PROVIDER\tMODEL\tFAMILY\tVERSION\tTIER\tPOWER\tCOST/M\tSTATUS\tQUOTA\tAUTO")
	for _, model := range models {
		fmt.Fprintf(tw, "%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\t%s\n",
			model.Provider,
			model.ID,
			emptyDash(model.Family),
			formatVersion(model.Version),
			formatTier(model.Tier),
			formatModelPower(model.Power),
			formatModelCost(model.CostInputPerM, model.CostOutputPerM),
			model.Status,
			emptyDash(model.QuotaPool),
			formatAuto(model),
		)
	}
	_ = tw.Flush()
	return 0
}

func filterModelRows(models []modelregistry.KnownModel, opts modelsCommandOptions) []modelregistry.KnownModel {
	filtered := make([]modelregistry.KnownModel, 0, len(models))
	for _, model := range models {
		if opts.Provider != "" && model.Provider != opts.Provider {
			continue
		}
		if opts.PowerMin > 0 && model.Power < opts.PowerMin {
			continue
		}
		if opts.PowerMax > 0 && model.Power > opts.PowerMax {
			continue
		}
		filtered = append(filtered, model)
	}
	if !opts.IncludeNoise {
		filtered = suppressModelNoise(filtered)
	}
	sort.SliceStable(filtered, func(i, j int) bool {
		if filtered[i].Provider != filtered[j].Provider {
			return filtered[i].Provider < filtered[j].Provider
		}
		if filtered[i].Family != filtered[j].Family {
			return filtered[i].Family < filtered[j].Family
		}
		if cmp := compareVersions(filtered[i].Version, filtered[j].Version); cmp != 0 {
			return cmp > 0
		}
		return filtered[i].ID < filtered[j].ID
	})
	return filtered
}

func suppressModelNoise(models []modelregistry.KnownModel) []modelregistry.KnownModel {
	type groupKey struct {
		provider string
		family   string
		tier     modelcatalog.Tier
	}
	versionsByGroup := map[groupKey]map[string][]int{}
	for _, model := range models {
		if model.Power < 3 {
			continue
		}
		if model.Tier == modelcatalog.TierUnknown && model.Power == 0 {
			continue
		}
		key := groupKey{provider: model.Provider, family: model.Family, tier: model.Tier}
		if key.family == "" {
			continue
		}
		if versionsByGroup[key] == nil {
			versionsByGroup[key] = map[string][]int{}
		}
		versionsByGroup[key][formatVersion(model.Version)] = model.Version
	}

	allowedVersions := map[groupKey]map[string]bool{}

	allowedVersions := map[groupKey]map[string]bool{}
	for key, versions := range versionsByGroup {
		list := make([][]int, 0, len(versions))
		for _, version := range versions {
			list = append(list, version)
		}
		sort.Slice(list, func(i, j int) bool { return compareVersions(list[i], list[j]) > 0 })
		allowedVersions[key] = map[string]bool{}
		for i, version := range list {
			if i >= 2 {
				break
			}
			allowedVersions[key][formatVersion(version)] = true
		}
	}

	out := make([]modelregistry.KnownModel, 0, len(models))
	for _, model := range models {
		if model.Configured {
			out = append(out, model)
			continue
		}
		if model.Power < 3 {
			continue
		}
		if model.Tier == modelcatalog.TierUnknown && model.Power == 0 {
			continue
		}
		key := groupKey{provider: model.Provider, family: model.Family, tier: model.Tier}
		if allowedVersions[key] != nil && !allowedVersions[key][formatVersion(model.Version)] {
			continue
		}
		out = append(out, model)
	}
	if len(out) == 0 {
		return models
	}
	return out
}

func cmdModelsDetail(snapshot modelregistry.ModelSnapshot, cfg *agentConfig.Config, cat *modelcatalog.Catalog, cache *discoverycache.Cache, opts modelsCommandOptions) int {
	model, err := resolveModelRef(snapshot.Models, opts.Ref)
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		return 1
	}

	detail := buildModelDetail(snapshot, cfg, cat, cache, model)
	if opts.JSON {
		data, err := json.MarshalIndent(detail, "", "  ")
		if err != nil {
			fmt.Fprintf(os.Stderr, "error: %s\n", err)
			return 1
		}
		fmt.Println(string(data))
		return 0
	}

	fmt.Printf("Canonical: %s\n", detail.CanonicalID)
	fmt.Printf("KnownModel: %+v\n", detail.KnownModel)
	if detail.CatalogEntry != nil {
		fmt.Printf("CatalogEntry: %+v\n", *detail.CatalogEntry)
	} else {
		fmt.Println("CatalogEntry: -")
	}
	if len(detail.RawDiscoveryData) > 0 {
		fmt.Printf("RawDiscoveryData: %s\n", string(detail.RawDiscoveryData))
	} else {
		fmt.Println("RawDiscoveryData: -")
	}
	if detail.RuntimeSignal != nil {
		fmt.Printf("RuntimeSignal: %+v\n", *detail.RuntimeSignal)
	} else {
		fmt.Println("RuntimeSignal: -")
	}
	fmt.Printf("AutoRoutable: %t", detail.AutoRoutable.AutoRoutable)
	if detail.AutoRoutable.BlockedBy != "" {
		fmt.Printf(" blocked_by=%s", detail.AutoRoutable.BlockedBy)
	}
	fmt.Println()
	return 0
}

func resolveModelRef(models []modelregistry.KnownModel, ref string) (modelregistry.KnownModel, error) {
	ref = strings.TrimSpace(ref)
	if strings.Contains(ref, "/") {
		provider, id, ok := strings.Cut(ref, "/")
		if !ok || provider == "" || id == "" {
			return modelregistry.KnownModel{}, fmt.Errorf("invalid model ref %q", ref)
		}
		for _, model := range models {
			if model.Provider == provider && model.ID == id {
				return model, nil
			}
		}
		return modelregistry.KnownModel{}, fmt.Errorf("unknown model ref %q", ref)
	}

	var matches []modelregistry.KnownModel
	lower := strings.ToLower(ref)
	for _, model := range models {
		id := strings.ToLower(model.ID)
		if id == lower || strings.Contains(id, lower) {
			matches = append(matches, model)
		}
	}
	sort.Slice(matches, func(i, j int) bool { return canonicalModelID(matches[i]) < canonicalModelID(matches[j]) })
	switch len(matches) {
	case 0:
		return modelregistry.KnownModel{}, fmt.Errorf("no model matched %q\n%s", ref, formatModelSuggestions(models, ref))
	case 1:
		return matches[0], nil
	default:
		return modelregistry.KnownModel{}, fmt.Errorf("ambiguous model ref %q\nCandidates:\n%s", ref, formatModelCandidates(matches))
	}
}

func buildModelDetail(snapshot modelregistry.ModelSnapshot, cfg *agentConfig.Config, cat *modelcatalog.Catalog, cache *discoverycache.Cache, model modelregistry.KnownModel) modelDetail {
	detail := modelDetail{
		CanonicalID:       canonicalModelID(model),
		KnownModel:        model,
		RawDiscoveryData:  rawDiscoveryData(cache, model.Provider),
		AutoRoutable:      autoRoutableBreakdown(model, cfg),
		SourceMeta:        snapshot.Sources[model.Provider],
		SnapshotGenerated: snapshot.AsOf,
	}
	if cat != nil {
		if entry, ok := cat.LookupModel(model.ID); ok {
			detail.CatalogEntry = &entry
		}
	}
	if cache != nil {
		if sig, ok := runtimesignals.ReadCached(cache, model.Provider); ok {
			detail.RuntimeSignal = sig
		}
	}
	return detail
}

func rawDiscoveryData(cache *discoverycache.Cache, provider string) json.RawMessage {
	if cache == nil {
		return nil
	}
	result, err := cache.Read(discoverycache.Source{
		Tier:            "discovery",
		Name:            provider,
		TTL:             24 * time.Hour,
		RefreshDeadline: 10 * time.Second,
	})
	if err != nil || result.Data == nil {
		return nil
	}
	return json.RawMessage(result.Data)
}

func autoRoutableBreakdown(model modelregistry.KnownModel, cfg *agentConfig.Config) autoRoutableComposition {
	providerOK := true
	if cfg != nil {
		if pc, ok := cfg.Providers[model.Provider]; ok && pc.IncludeByDefault != nil {
			providerOK = *pc.IncludeByDefault
		}
	}
	catalogOK := model.Power > 0 && model.ExclusionReason != "catalog_unknown" && model.ExclusionReason != "catalog_not_auto_routable"
	statusOK := model.Status != modelregistry.StatusUnreachable && model.Status != modelregistry.StatusUnknown
	return autoRoutableComposition{
		AutoRoutable: model.AutoRoutable,
		BlockedBy:    model.ExclusionReason,
		Provider:     providerOK,
		Catalog:      catalogOK,
		Status:       statusOK,
	}
}

func cmdCachePrune(workDir string) int {
	cfg, err := agentConfig.Load(workDir)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}
	root, err := modelCacheRoot()
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}
	cache := &discoverycache.Cache{Root: root}
	if err := cache.Prune(modelregistry.ActiveSources(cfg)); err != nil {
		fmt.Fprintf(os.Stderr, "error: %s\n", err)
		return 1
	}
	fmt.Println("cache pruned")
	return 0
}

func canonicalModelID(model modelregistry.KnownModel) string {
	return model.Provider + "/" + model.ID
}

func formatModelCandidates(models []modelregistry.KnownModel) string {
	lines := make([]string, 0, len(models))
	for _, model := range models {
		lines = append(lines, "  "+canonicalModelID(model))
	}
	return strings.Join(lines, "\n")
}

func formatModelSuggestions(models []modelregistry.KnownModel, ref string) string {
	type scored struct {
		model modelregistry.KnownModel
		score int
	}
	scoredModels := make([]scored, 0, len(models))
	for _, model := range models {
		score := levenshtein(strings.ToLower(ref), strings.ToLower(model.ID))
		scoredModels = append(scoredModels, scored{model: model, score: score})
	}
	sort.Slice(scoredModels, func(i, j int) bool {
		if scoredModels[i].score != scoredModels[j].score {
			return scoredModels[i].score < scoredModels[j].score
		}
		return canonicalModelID(scoredModels[i].model) < canonicalModelID(scoredModels[j].model)
	})
	limit := len(scoredModels)
	if limit > 5 {
		limit = 5
	}
	if limit == 0 {
		return "Suggestions: -"
	}
	lines := make([]string, 0, limit)
	for i := 0; i < limit; i++ {
		lines = append(lines, "  "+canonicalModelID(scoredModels[i].model))
	}
	return "Suggestions:\n" + strings.Join(lines, "\n")
}

func formatVersion(version []int) string {
	if len(version) == 0 {
		return "-"
	}
	parts := make([]string, len(version))
	for i, part := range version {
		parts[i] = strconv.Itoa(part)
	}
	return strings.Join(parts, ".")
}

func formatTier(tier modelcatalog.Tier) string {
	switch tier {
	case modelcatalog.TierSmart:
		return "smart"
	case modelcatalog.TierStandard:
		return "standard"
	case modelcatalog.TierCheap:
		return "cheap"
	default:
		return "unknown"
	}
}

func formatModelPower(power int) string {
	if power <= 0 {
		return "-"
	}
	return strconv.Itoa(power)
}

func formatModelCost(input, output float64) string {
	if input == 0 && output == 0 {
		return "-"
	}
	return fmt.Sprintf("%.2f/%.2f", input, output)
}

func formatAuto(model modelregistry.KnownModel) string {
	if model.AutoRoutable {
		return "yes"
	}
	if model.ExclusionReason != "" {
		return "no(" + model.ExclusionReason + ")"
	}
	return "no"
}

func compareVersions(a, b []int) int {
	max := len(a)
	if len(b) > max {
		max = len(b)
	}
	for i := 0; i < max; i++ {
		var av, bv int
		if i < len(a) {
			av = a[i]
		}
		if i < len(b) {
			bv = b[i]
		}
		if av != bv {
			return av - bv
		}
	}
	return 0

// Package runtimesignals collects volatile per-provider runtime signals
// (status, quota remaining, recent p50 latency) and writes them to the
// runtime tier of M1's per-source on-disk cache (ADR-012). M2's snapshot
// assembler reads the cache files to populate KnownModel.Status,
// .QuotaRemaining, and .RecentP50Latency.
package runtimesignals

import "time"

// ModelStatus represents the operational availability of a provider.
type ModelStatus string

const (
	StatusAvailable ModelStatus = "available"
	StatusDegraded  ModelStatus = "degraded"
	StatusExhausted ModelStatus = "exhausted"
	StatusUnknown   ModelStatus = "unknown"
)

// Signal is the runtime state snapshot for one provider. It is serialized as
// JSON to runtime/<provider>.json in M1's cache directory.
type Signal struct {
	Provider         string        `json:"provider"`
	Status           ModelStatus   `json:"status"`
	QuotaRemaining   *int          `json:"quota_remaining,omitempty"`
	QuotaResetAt     *time.Time    `json:"quota_reset_at,omitempty"`
	RecentP50Latency time.Duration `json:"recent_p50_latency_ns"`
	LastSuccessAt    *time.Time    `json:"last_success_at,omitempty"`
	LastErrorAt      *time.Time    `json:"last_error_at,omitempty"`
	LastErrorMsg     string        `json:"last_error_msg,omitempty"`
	RecordedAt       time.Time     `json:"recorded_at"`
}

